metadata.preview:
        for c in range(0x30A0, 0x30FF + 1):
            chars.add(chr(c))
        # Кандзи (CJK Unified Ideographs)
        for c in range(0x4E00, 0x9FFF + 1):
            chars.add(chr(c))
        # Японская пунктуация
        for c in range(0x3000, 0x303F + 1):
            chars.add(chr(c))
    return chars

def _filter_by_language(self, text: str) -> str:
