        panel.btn_start = QRect(bx, by, _PANEL_BTN, _PANEL_BTN); bx += _PANEL_BTN + _PANEL_GAP
        panel.btn_stop = QRect(bx, by, _PANEL_BTN, _PANEL_BTN)

        # ▼ toggle in name bar
